WITH hourly_stats AS ( SELECT td.t_meal_time, wp.wp_type, td.t_hour, SUM(wr.wr_return_amt) AS hour_return_amt, SUM(wr.wr_net_loss) AS hour_net_loss FROM web_returns wr JOIN time_dim td ON wr.wr_returned_time_sk = td.t_time_sk JOIN web_page wp ON wr.wr_web_page_sk = wp.wp_web_page_sk GROUP BY td.t_meal_time, wp.wp_type, td.t_hour ), with_moving AS ( SELECT t_meal_time, wp_type, t_hour, hour_return_amt, hour_net_loss, PERCENT_RANK() OVER (PARTITION BY wp_type ORDER BY hour_return_amt) AS pct_rank_return_amt FROM hourly_stats ) SELECT t_meal_time, wp_type, t_hour, hour_return_amt, hour_net_loss, pct_rank_return_amt, CASE WHEN pct_rank_return_amt > 0.9 THEN 'Top 10% Loss' ELSE 'Normal' END AS loss_category FROM with_moving ORDER BY wp_type, t_hour
